 3	public final class BinarySearch {
 4	    public static final int NOT_FOUND = -1;
 5	
 6	    private BinarySearch() {
 7	    }
 8	
 9	    public static int binarySearch(final int[] sortedValues, final int target) {
10	        Objects.requireNonNull(sortedValues, "sortedValues must not be null");
11	
12	        int low = 0;
13	        int high = sortedValues.length - 1;
14	
15	        while (low <= high) {
16	            final int mid = low + (high - low) / 2;
17	            final int midValue = sortedValues[mid];
18	
19	            if (midValue == target) {
20	                return mid;
21	            }
22	
23	            if (midValue < target) {
24	                low = mid + 1;
25	            } else {
26	                high = mid - 1;
27	            }
28	        }
29	
30	        return NOT_FOUND;
31	    }
32	
33	    public static void main(final String[] args) {
34	        BinarySearchDemo.main(args);
35	    }
36	}

